                            "after" to SdkClient.queryValue(request.after, "form", true),
                            "before" to SdkClient.queryValue(request.before, "form", true),
                            "filter" to SdkClient.queryValue(request.filter, "form", true),
                        ),
                    operationId = "listVectorStoreFiles",
