    /**
     * Lists files attached to a vector store, with pagination and an optional status filter. Use
     * `after` or `before` to navigate the list, and `filter` to select files by processing status.
     *
     * Returns a list of vector store files.
     *
     * @param vectorStoreId The ID of the vector store that the files belong to.
     * @param limit A limit on the number of objects to be returned. Limit can range between 1 and
     *   100, and the default is 20.
     * @param order Sort order by the `created_at` timestamp of the objects. `asc` for ascending
     *   order and `desc` for descending order.
     * @param after A cursor for use in pagination. `after` is an object ID that defines your place
     *   in the list. For instance, if you make a list request and receive 100 objects, ending with
     *   obj_foo, your subsequent call can include after=obj_foo in order to fetch the next page of
     *   the list.
     * @param before A cursor for use in pagination. `before` is an object ID that defines your
     *   place in the list. For instance, if you make a list request and receive 100 objects,
     *   starting with obj_foo, your subsequent call can include before=obj_foo in order to fetch
     *   the previous page of the list.
     * @param filter Filter by file status. One of `in_progress`, `completed`, `failed`,
     *   `cancelled`.
     */
    fun listVectorStoreFilesPaginated(
        clientConfig: ClientConfig,
        request: ListVectorStoreFilesRequest,
        options: RequestOptions? = null,
        yieldFn: (VectorStoreFileObject) -> Boolean,
    ) {
        var cursor = request.after
        while (true) {
            val page = listVectorStoreFiles(clientConfig, request.copy(after = cursor), options)
            val items = page.`data`.orEmpty()
            if (items.isEmpty()) return
            for (item in items) {
                if (!yieldFn(item)) return
            }
            if (page.hasMore != true) return
            val nextCursor = page.lastId
            cursor = nextCursor
        }
    }

    data class ListVectorStoreFilesPage(
        val data: ListVectorStoreFilesResponse,
        val items: List<VectorStoreFileObject>,
        val hasMore: Boolean,
    )

    fun listVectorStoreFilesPages(
        clientConfig: ClientConfig,
        request: ListVectorStoreFilesRequest,
        options: RequestOptions? = null,
        yieldPage: (ListVectorStoreFilesPage) -> Boolean,
    ) {
        var cursor = request.after
        while (true) {
            val page = listVectorStoreFiles(clientConfig, request.copy(after = cursor), options)
            val items = page.`data`.orEmpty()
            if (items.isEmpty()) return
            val nextCursor = page.lastId
            val hasMore = page.hasMore == true
            if (!yieldPage(ListVectorStoreFilesPage(page, items, hasMore))) return
            if (!hasMore) return
            cursor = nextCursor
        }
    }

