    /**
     * Searches a vector store for relevant file chunks using one or more queries and optional
     * file-attribute filters. Set `max_num_results` to control the result count and
     * `ranking_options` to configure ranking; use `next_page` to continue when more results are
     * available.
     *
     * Search a vector store for relevant chunks based on a query and file attributes filter.
     *
     * @param vectorStoreId The ID of the vector store to search.
     * @param query A query string for a search
     * @param rewriteQuery Whether to rewrite the natural language query for vector search.
     * @param maxNumResults The maximum number of results to return. This number should be between 1
     *   and 50 inclusive.
     * @param filters A filter to apply based on file attributes.
     * @param rankingOptions Ranking options for search.
     */
    fun searchVectorStore(
        clientConfig: ClientConfig,
        request: SearchVectorStoreRequest,
        options: RequestOptions? = null,
    ): VectorStoreSearchResultsPage {
        validateSearchVectorStoreRequest(request)

        return SdkClient.request<VectorStoreSearchResultsPage>(
                SdkClient.RequestSpec(
                    "POST",
                    "/vector_stores/${SdkClient.encodePathSegment(request.vectorStoreId)}/search",
                    config = clientConfig,
                    body =
                        SdkClient.bodyMap(
                            "query" to (request.query),
                            "rewrite_query" to (SdkClient.omitIfNull(request.rewriteQuery)),
                            "max_num_results" to (SdkClient.omitIfNull(request.maxNumResults)),
                            "filters" to (SdkClient.omitIfNull(request.filters)),
                            "ranking_options" to (SdkClient.omitIfNull(request.rankingOptions)),
                        ),
                    operationId = "searchVectorStore",
                    decoder = SdkClient.ResponseDecoder.JSON,
                    options = options,
                    errors =
                        mapOf(
                            "400" to ErrorResponse::class.java,
                            "404" to ErrorResponse::class.java,
                            "429" to ErrorResponse::class.java,
                        ),
                )
            )
            .data
    }

    private fun validateSearchVectorStoreRequest(request: SearchVectorStoreRequest) {
        if (request.maxNumResults != null) {
            Validation.validateRange(
                "max_num_results",
                request.maxNumResults,
                Validation.RangeOpts(min = 1.0, max = 50.0),
            )
        }
    }
